<?php if($overview['timer']): ?><section class="card work-running-timer"><span class="work-timer-dot"></span><div><strong>Timer running: <?= e($overview['timer']['identifier'].'-'.$overview['timer']['sequence']) ?></strong><p><?= e($overview['timer']['title']) ?></p></div><strong data-work-timer="<?= e($overview['timer']['started_at']) ?>">Running</strong><a href="/work/issue/<?= e($overview['timer']['issue_id']) ?>#work-time">Open timer</a></section><?php endif; ?>
<?php if($tab==='overview'): ?><div class="work-stats"><?php foreach([['Projects',count($overview['projects'])],['Work items',$overview['stats']['total']],['Completed',$overview['stats']['completed']],['Overdue',$overview['stats']['overdue']]] as [$label,$count]): ?><section class="card"><span><?= e($label) ?></span><strong><?= e($count) ?></strong></section><?php endforeach; ?></div>
<div class="two-col"><section class="card"><div class="section-heading"><h2>Your projects</h2><a href="/work?workspace=<?= e($workspace['id']) ?>&amp;tab=projects#new-project">+ Project</a></div><?php if(!$overview['projects']): ?><div class="empty"><h3>One project. A little more clarity.</h3><p>Add your first project to start organising work.</p></div><?php else:foreach(array_slice($overview['projects'],0,6) as $project): ?><a class="work-project-row" href="/work/project/<?= e($project['id']) ?>"><span class="work-project-mark"><?= e(mb_substr($project['identifier'],0,2)) ?></span><span><strong><?= e($project['name']) ?></strong><small><?= e($project['identifier']) ?> · <?= e(ucfirst($project['kind'])) ?></small></span><span class="badge"><?= e($project['issue_count']) ?> items</span><?= icon('arrow-right') ?></a><?php endforeach;endif; ?></section><section class="card"><div class="section-heading"><h2>My work</h2><a href="/work?workspace=<?= e($workspace['id']) ?>&amp;tab=mine">View all</a></div><?php if(!$overview['mine']): ?><div class="empty"><h3>A little breathing room.</h3><p>Items assigned to you will appear here.</p></div><?php else:foreach(array_slice($overview['mine'],0,6) as $workRow): ?><a class="work-compact-issue" href="/work/issue/<?= e($workRow['id']) ?>"><span class="work-state-dot" data-work-color="<?= e($workRow['state_color']) ?>"></span><span><small><?= e($workRow['identifier'].'-'.$workRow['sequence']) ?></small><strong><?= e($workRow['title']) ?></strong></span><?php if($workRow['due_date']): ?><time><?= e($workRow['due_date']) ?></time><?php endif; ?></a><?php endforeach;endif; ?></section></div>
<?php if($overview['favorites']): ?><section class="card"><h2>Favourites</h2><div class="work-favorites"><?php foreach($overview['favorites'] as $favorite): ?><a href="<?= e($favorite['route']) ?>"><?= icon('target') ?><?= e($favorite['title']) ?></a><?php endforeach; ?></div></section><?php endif; ?>
<section class="card"><div class="section-heading"><h2>Workspace activity</h2><span class="badge">Latest actions</span></div><?php if(!$overview['activity']): ?><p class="muted">Your project updates will appear here.</p><?php else:foreach(array_slice($overview['activity'],0,12) as $event): ?><article class="studio-activity"><span class="studio-activity-mark"><?= icon('check') ?></span><div><strong><?= e(str_replace('.',' · ',$event['event'])) ?></strong><p><?= e($event['project_name']) ?> · <?= e($event['actor_name']) ?><?= $event['detail']!==''?' · '.e(mb_strimwidth($event['detail'],0,100,'…')):'' ?></p></div><time><?= e($event['created_at']) ?></time></article><?php endforeach;endif; ?></section>
