<?php if($tab==='projects'): ?><section class="card" id="new-project"><h2>Create a project</h2><?php $projectEditing=null;$projectFormAction='/work/workspace/'.$workspace['id'].'/projects';require __DIR__.'/project-form.php'; ?></section><?php endif; ?>
<?php elseif(in_array($tab,['mine','intake'],true)): $workRows=$tab==='mine'?$overview['mine']:$overview['intake']; ?><section class="card"><div class="section-heading"><div><h2><?= $tab==='mine'?'My work':'Intake & triage' ?></h2><p class="muted"><?= $tab==='mine'?'Work items assigned to your local workspace identity.':'Review incoming requests, accept them into a project or keep rejected requests in their history.' ?></p></div><span class="badge"><?= count($workRows) ?> items</span></div><?php if(!$workRows): ?><div class="empty"><h3><?= $tab==='mine'?'Nothing assigned to you yet.':'Your intake is clear.' ?></h3><p><?= $tab==='mine'?'Assign yourself to a work item in a project.':'Create a work item with Intake selected when logging a new request.' ?></p></div><?php else:foreach($workRows as $workRow): ?><article class="work-inbox-row"><a href="/work/issue/<?= e($workRow['id']) ?>"><small><?= e($workRow['project_name']) ?> · <?= e($workRow['identifier'].'-'.$workRow['sequence']) ?></small><strong><?= e($workRow['title']) ?></strong></a><?php if($tab==='intake'): ?><div class="hero-actions"><?php foreach(['accept'=>'Accept','reject'=>'Reject'] as $action=>$label): ?><form method="post" action="/work/project/<?= e($workRow['project_id']) ?>/issues/<?= e($workRow['id']) ?>/lifecycle"><?= csrf_field() ?><input type="hidden" name="version" value="<?= e($workRow['version']) ?>"><input type="hidden" name="action" value="<?= $action ?>"><button class="secondary"><?= $label ?></button></form><?php endforeach; ?></div><?php else: ?><span class="badge"><?= e($workRow['state_name']) ?></span><?php endif; ?></article><?php endforeach;endif; ?></section>
<?php elseif($tab==='people'): ?><section class="card"><h2>People &amp; assignees</h2><p class="muted">Local project contacts used for assignments and time records. These records do not create online accounts or send invitations.</p><?php foreach($people as $person): ?><details class="work-person"><summary><span class="work-avatar"><?= e(mb_substr($person['name'],0,1)) ?></span><strong><?= e($person['name']) ?></strong><span class="badge"><?= $person['is_self']?'You':($person['active']?'Active':'Inactive') ?></span></summary><form class="form-grid" method="post" action="/work/workspace/<?= e($workspace['id']) ?>/people"><?= csrf_field() ?><input type="hidden" name="person_id" value="<?= e($person['id']) ?>"><label>Name<input name="name" value="<?= e($person['name']) ?>" maxlength="120" required></label><label>Email (optional)<input type="email" name="email" value="<?= e($person['email']) ?>" maxlength="254"></label><label>Status<select name="active"><option value="1" <?= $person['active']?'selected':'' ?>>Active</option><?php if(!$person['is_self']): ?><option value="0" <?= !$person['active']?'selected':'' ?>>Inactive</option><?php endif; ?></select></label><div class="full"><button class="secondary">Save person</button></div></form></details><?php endforeach; ?></section><section class="card"><h2>Add an assignee</h2><form class="form-grid" method="post" action="/work/workspace/<?= e($workspace['id']) ?>/people"><?= csrf_field() ?><label>Name<input name="name" maxlength="120" required></label><label>Email (optional)<input type="email" name="email" maxlength="254"></label><div class="full"><button>Add person</button></div></form></section>
<?php elseif($tab==='settings'): ?><section class="card"><h2>Workspace settings</h2><form class="form-grid" method="post" action="/work/workspace/<?= e($workspace['id']) ?>/save"><?= csrf_field() ?><label class="full">Name<input name="name" value="<?= e($workspace['name']) ?>" maxlength="120" required></label><label class="full">Description<textarea name="description" maxlength="3000" rows="4"><?= e($workspace['description']) ?></textarea></label><div class="full"><button>Save workspace</button></div></form></section><section class="card"><h2>Local work, connected to your life.</h2><p class="muted">Work deadlines appear in LifeOS reminders. Project attachments use Documents storage and encrypted backups. A project can link to a website/business workspace without changing website content or money balances.</p><a href="/settings">LifeOS backup &amp; privacy settings</a></section><?php endif; endif; ?>
